import{_ as t,o as r,c as i,a7 as o}from"./chunks/framework.Cv3pX6x0.js";const d=JSON.parse('{"title":"Setup requirements","description":"Setup requirements for Axolotl-PM. It requires a 64-bit CPU, a 64-bit operating system and 1GB RAM or better.","frontmatter":{"title":"Setup requirements","outline":"deep","description":"Setup requirements for Axolotl-PM. It requires a 64-bit CPU, a 64-bit operating system and 1GB RAM or better.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/installation/requirements"}]]},"headers":[],"relativePath":"docs/installation/requirements.md","filePath":"docs/installation/requirements.md","lastUpdated":1790689997000}'),a={name:"docs/installation/requirements.md"};function s(n,e,l,u,p,c){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="setup-requirements" tabindex="-1">Setup requirements <a class="header-anchor" href="#setup-requirements" aria-label="Permalink to &quot;Setup requirements&quot;">​</a></h1><p>A computer or device with the following is required:</p><ul><li>64-bit CPU</li><li>64-bit operating system</li><li>1GB RAM or better</li></ul><p>The following are not requirements, but recommended:</p><ul><li>Dual-core or better CPU</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>Axolotl-PM is notoriously bad at multi-core usage. If purchasing a machine to run Axolotl-PM on, prefer higher CPU frequency instead of lots of cores.</p></div><p>We officially try to support Windows, Linux and MacOS platforms. However, in general any platform which will run 64-bit PHP with the required extensions will work.</p>',7)])])}const f=t(a,[["render",s]]);export{d as __pageData,f as default};
